(function(){'use strict';
const M=window.RangePlans,get=id=>document.getElementById(id),schedules=[{id:'normal',name:'Обычный день',color:'#005faf'},{id:'short',name:'Сокращённый день',color:'#00875f'},{id:'exam',name:'Экзамены',color:'#875faf'}];
let plans=[{id:'p1',name:'Учебный год 2026–2027',start:'2026-09-01',end:'2027-05-31',schedule_ids:['normal','short'],days:M.dates('2026-09-01','2027-05-31').map(d=>{const w=new Date(d+'T00:00:00Z').getUTCDay();return w===0||w===6?'.':w===5?'B':'A';}).join('')},{id:'p2',name:'Экзамены — июнь 2027',start:'2027-06-01',end:'2027-06-20',schedule_ids:['exam'],days:'A'+'.'.repeat(19)}],selected='p1',brush='view',offset=0,editing=false,copyFrom=null,next=3,drag=false;
if(new URLSearchParams(location.search).has('empty')){plans=[];selected=null;}
const current=()=>plans.find(p=>p.id===selected),label=id=>schedules.find(s=>s.id===id)?.name||'Тихий день';
function message(s){get('range-message').textContent=s;}
function assigned(p,i){const c=p.days[i];return c==='.'?'quiet':p.schedule_ids[c.charCodeAt(0)-65];}
function fill(){const p=current();editing=false;copyFrom=null;get('range-name').value=p?.name||'';get('range-start').value=p?.start||'';get('range-end').value=p?.end||'';if(p){get('bulk-start').value=p.start;get('bulk-end').value=p.end;}render();}
function canLeave(){return !editing||confirm('Отменить неприменённый ввод названия и дат? Раскраска не будет отменена.');}
function paint(indices){const p=current();if(!p||brush==='view')return;const chars=p.days.split('');let slot=p.schedule_ids.indexOf(brush);if(brush!=='quiet'&&slot<0){slot=p.schedule_ids.length;p.schedule_ids.push(brush);}for(const i of indices)chars[i]=brush==='quiet'?'.':String.fromCharCode(65+slot);p.days=chars.join('');M.validate(plans);message('Назначения изменены только в прототипе.');render(false);}
function showDay(date,i){get('day-preview').textContent=date+' · '+label(assigned(current(),i))+' · предпросмотр без изменения.';}
function render(rebuild=true){
const p=current(),list=get('range-list');list.replaceChildren();for(const plan of plans){const b=document.createElement('button');b.type='button';b.textContent=plan.name+'\n'+plan.start+' — '+plan.end;b.setAttribute('aria-pressed',String(plan.id===selected));b.onclick=()=>{if(canLeave()){selected=plan.id;offset=0;brush='view';fill();message('План выбран для редактирования.');}};list.appendChild(b);}
get('range-budget').textContent='Назначения дат: '+plans.reduce((n,p)=>n+p.days.length,0)+' дней · планов '+plans.length+' / 8 (предварительный лимит)';get('range-heading').textContent=p?p.name:copyFrom?'Копия плана':plans.length?'Новый план':'План ещё не создан';get('range-tools').hidden=!p;get('range-delete').disabled=!p;get('range-copy').disabled=!p;get('range-json').textContent=p?JSON.stringify(p,null,2):'';
if(!p){get('range-grid').replaceChildren();return;}const dates=M.dates(p.start,p.end),months=[...new Set(dates.map(d=>d.slice(0,7)))];offset=Math.max(0,Math.min(offset,Math.max(0,months.length-1)));const visible=months.slice(offset,offset+3);
get('months-prev').disabled=offset===0;get('months-next').disabled=offset+3>=months.length;get('months-label').textContent=visible[0]+' — '+visible.at(-1)+' · всего '+months.length+' месяцев';
const tools=get('range-brushes');tools.replaceChildren();for(const tool of [{id:'view',name:'Просмотр дня'},{id:'quiet',name:'Тихий день / ластик'},...schedules]){const b=document.createElement('button');b.type='button';b.textContent=tool.name;b.style.borderLeftColor=tool.color||'var(--muted)';b.setAttribute('aria-pressed',String(tool.id===brush));b.onclick=()=>{brush=tool.id;render();};tools.appendChild(b);}
get('range-tool-status').textContent=brush==='view'?'Просмотр: даты не изменяются.':'Раскраска: '+label(brush)+'. Нажимайте даты или протяните мышью.';get('bulk-apply').disabled=brush==='view';
if(!rebuild){document.querySelectorAll('#range-grid [data-index]').forEach(b=>decorate(b,assigned(p,Number(b.dataset.index))));return;}
const grid=get('range-grid');grid.replaceChildren();for(const month of visible){const box=document.createElement('section');box.className='calendar-month';const h=document.createElement('h3');h.textContent=new Date(month+'-01T00:00:00Z').toLocaleDateString('ru-RU',{month:'long',year:'numeric',timeZone:'UTC'});box.appendChild(h);const days=document.createElement('div');days.className='month-days';for(const w of ['Пн','Вт','Ср','Чт','Пт','Сб','Вс']){const span=document.createElement('span');span.textContent=w;days.appendChild(span);}const first=dates.findIndex(d=>d.startsWith(month));let weekday=(new Date(dates[first]+'T00:00:00Z').getUTCDay()+6)%7;for(let k=0;k<weekday;k++)days.appendChild(document.createElement('span'));
dates.forEach((date,i)=>{if(!date.startsWith(month))return;const b=document.createElement('button');b.type='button';b.className='calendar-day';b.textContent=Number(date.slice(-2));b.dataset.index=i;b.title=date;b.setAttribute('aria-label',date+' '+label(assigned(p,i)));decorate(b,assigned(p,i));b.onpointerdown=e=>{if(brush!=='view'&&e.pointerType==='mouse'&&e.button===0){e.preventDefault();drag=true;paint([i]);}};b.onpointerenter=e=>{if(drag&&(e.buttons&1))paint([i]);};b.onclick=()=>brush==='view'?showDay(date,i):paint([i]);days.appendChild(b);});box.appendChild(days);grid.appendChild(box);}
}
function decorate(b,id){b.setAttribute('aria-label',b.title+' '+label(id));const s=schedules.find(s=>s.id===id);b.style.background=s?.color||'';b.style.color=s?'white':'';}
for(const id of ['range-name','range-start','range-end'])get(id).oninput=()=>editing=true;
get('range-new').onclick=()=>{if(!canLeave())return;selected=null;fill();const trusted=get('range-clock').value==='trusted',proposal=M.suggest('2026-10-26',trusted);get('range-name').value=proposal?.name||'Новый план';get('range-start').value=proposal?.start||'';get('range-end').value=proposal?.end||'';editing=true;message(proposal?'Предложен учебный год по тестовой подтверждённой дате. Проверьте даты и создайте план.':'Дата не подтверждена. Проверьте часы или укажите диапазон вручную.');};
get('range-cancel').onclick=()=>{if(canLeave()){selected=current()?.id||plans[0]?.id;fill();message('Ввод отменён.');}};
get('range-copy').onclick=()=>{if(!canLeave())return;const source=JSON.parse(JSON.stringify(current()));selected=null;fill();copyFrom=source;get('range-name').value=source.name+' — копия';get('range-start').value=source.start;get('range-end').value=source.end;editing=true;render();message('Задайте новые непересекающиеся даты. Копия переносит назначения по порядку дней.');};
get('range-save').onclick=()=>{try{const p=current(),start=get('range-start').value,end=get('range-end').value,name=get('range-name').value.trim();let result,removed=0;if(p){const resized=M.resize(p,start,end,name);result=resized.plan;removed=resized.removed;}else{const count=M.dates(start,end).length;result={id:'p'+next,name,start,end,schedule_ids:copyFrom?[...copyFrom.schedule_ids]:[],days:copyFrom?(copyFrom.days+'.'.repeat(count)).slice(0,count):'.'.repeat(count)};}const candidate=plans.filter(x=>x.id!==result.id).concat([result]);M.validate(candidate);if(removed&&!confirm('За новыми границами будут удалены назначения '+removed+' дат. Продолжить?'))return;if(copyFrom&&!confirm('Скопировать по порядку дней? Дни недели могут отличаться. Проверьте результат.'))return;plans=candidate;if(!p)next++;selected=result.id;offset=0;fill();message('Название и диапазон применены в прототипе. Рабочий роутер не изменён.');}catch(e){message(e.message);}};
get('range-delete').onclick=()=>{const p=current();if(p&&confirm('Удалить «'+p.name+'» и все назначения внутри? Расписания и мелодии сохранятся.')){plans=plans.filter(x=>x.id!==p.id);selected=plans[0]?.id;offset=0;fill();message('План удалён только из прототипа.');}};
get('bulk-apply').onclick=()=>{try{const p=current(),all=M.dates(p.start,p.end),from=all.indexOf(get('bulk-start').value),to=all.indexOf(get('bulk-end').value);if(from<0||to<from)throw Error('Выберите даты внутри плана');const filter=get('bulk-filter').value,indices=[];for(let i=from;i<=to;i++){const w=new Date(all[i]+'T00:00:00Z').getUTCDay();if(filter==='all'||(filter==='weekdays'&&w>0&&w<6)||(filter==='weekends'&&(w===0||w===6)))indices.push(i);}if(confirm('Назначить «'+label(brush)+'» для '+indices.length+' дат?')){paint(indices);render();}}catch(e){message(e.message);}};
get('months-prev').onclick=()=>{offset=Math.max(0,offset-3);render();};get('months-next').onclick=()=>{offset+=3;render();};window.addEventListener('pointerup',()=>drag=false);window.addEventListener('blur',()=>drag=false);M.validate(plans);fill();
})();
